using System;using System.Drawing;using System.IO;using System.Diagnostics;using System.Runtime.InteropServices;using System.Windows.Forms;using WinBoard;
class FullscreenProbe {
 class TestWindow:Form {public bool IncludeInMonitorStack;protected override bool ShowWithoutActivation {get{return true;}}protected override CreateParams CreateParams{get{var p=base.CreateParams;if(!IncludeInMonitorStack)p.ExStyle|=0x08000000;return p;}}public TestWindow(){ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;}}
 [DllImport("dwmapi.dll")]static extern int DwmFlush();[DllImport("user32.dll")]static extern IntPtr GetShellWindow();
 static void Assert(bool value,string reason){if(!value)throw new Exception(reason);}
 static void Refresh(Form form){form.Refresh();Application.DoEvents();DwmFlush();}
 [STAThread]static void Main(){try{using(new CaptureDesktop.DpiScope())using(var dock=new TestWindow{Text="Dock monitor test",Bounds=new Rectangle(Screen.PrimaryScreen.Bounds.Left+30,Screen.PrimaryScreen.Bounds.Top+30,100,80)})using(var app=new TestWindow{Text="Window coverage test",Bounds=new Rectangle(Screen.PrimaryScreen.Bounds.Left+150,Screen.PrimaryScreen.Bounds.Top+150,500,300)}){
 var m=Screen.PrimaryScreen.Bounds;Assert(DockOcclusion.CoversMonitor(m,m),"exact full screen");Assert(DockOcclusion.CoversMonitor(Rectangle.FromLTRB(m.Left-8,m.Top-8,m.Right+8,m.Bottom+8),m),"overscan");Assert(!DockOcclusion.CoversMonitor(new Rectangle(m.Left,m.Top,m.Width,m.Height-40),m),"work area is not full screen");Assert(!DockOcclusion.CoversMonitor(new Rectangle(m.Left+3,m.Top,m.Width-3,m.Height),m),"three-pixel gap");Assert(!DockOcclusion.CoversMonitor(Rectangle.Empty,m),"invalid bounds");dock.Show();app.Show();Refresh(app);
 Assert(!DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"normal window must keep dock visible");app.WindowState=FormWindowState.Maximized;Refresh(app);Assert(DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"maximized window must hide dock");app.WindowState=FormWindowState.Normal;app.FormBorderStyle=FormBorderStyle.None;app.Bounds=m;Refresh(app);Assert(DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"borderless full screen must hide dock");Assert(!DockOcclusion.ShouldHide(app.Handle,dock.Handle,(uint)Process.GetCurrentProcess().Id),"own UI must keep dock visible");app.Bounds=new Rectangle(m.Left+150,m.Top+150,500,300);Refresh(app);Assert(!DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"leaving full screen must restore dock");
 using(var popup=new TestWindow{Text="Owned full screen video",FormBorderStyle=FormBorderStyle.None,Bounds=m}){popup.Show(app);Refresh(popup);Assert(DockOcclusion.ShouldHide(popup.Handle,dock.Handle,0),"full screen popup with normal owner");popup.Hide();}app.WindowState=FormWindowState.Minimized;Refresh(app);Assert(!DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"minimized window");Assert(!DockOcclusion.ShouldHide(GetShellWindow(),dock.Handle,0),"desktop excluded");
 string multi="single monitor geometry tested";if(Screen.AllScreens.Length>1){app.WindowState=FormWindowState.Normal;app.Bounds=Screen.AllScreens[0].DeviceName==Screen.PrimaryScreen.DeviceName?Screen.AllScreens[1].Bounds:Screen.AllScreens[0].Bounds;Refresh(app);using(var cover=new TestWindow{Text="Normal app above background",Bounds=new Rectangle(m.Left+80,m.Top+80,600,350),TopMost=true,IncludeInMonitorStack=true}){cover.Show();Refresh(cover);Assert(!DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"normal app above background full-screen video keeps Dock visible");cover.Hide();}multi="cross-monitor native window tested";using(var video=new TestWindow{Text="Full screen on Dock display",FormBorderStyle=FormBorderStyle.None,Bounds=m,TopMost=true}){video.Show();Refresh(video);Assert(DockOcclusion.ShouldHide(app.Handle,dock.Handle,0),"video remains full-screen while focus is on the other display");video.Hide();}}
 File.WriteAllText("pass.txt","PASS: normal/maximized/borderless fullscreen/restored/owned-popup/minimized/desktop/own-process and "+multi+"; no input injected.");}}
 catch(Exception ex){File.WriteAllText("error.txt",ex.ToString());Environment.ExitCode=1;}}
}
